            new SQLKomut(4,"",@"CREATE NONCLUSTERED INDEX[TASISLEMFORM_TAV2] ON[dbo].[TASSICILNOHAREKET] ([ISLEMTURUKOD],[DURUM]) INCLUDE([PRSICILNO], [SIRANO], [YIL], [MUHASEBEKOD], [HARCAMABIRIMKOD], [FISNO], [SICILNO], [HESAPPLANKOD], [AMBARKOD], [FIYAT], [KDVORAN], [ISLEMTIPIKOD], [ISLEMTARIH], [FISTARIH], [NEREYEGITTI], [KIMEGITTI], [KDVLIBIRIMFIYAT], [DEGERARTISI])",""),
            new SQLKomut(5,"",@"DROP VIEW[dbo].[TASDEMIRBASVIEW]",""),
            new SQLKomut(6,"",@"CREATE VIEW[dbo].[TASDEMIRBASVIEW] AS SELECT SICILNO, HESAPPLANKOD, HESAPPLANAD, '' KISIAD, '' ODAAD, ADI, YAZARADI, DISSICILNO, YAYINTARIHI, CILTNO, YERIKONUSU, TASAMBARSICILVIEW.PRSICILNO, SASENO, MUHASEBEKOD, HARCAMABIRIMKOD,  AMBARKOD, '' KIMEGITTI, '' NEREYEGITTI, TASSICILNORFID.RFIDNO, KDVORAN, KDVLIBIRIMFIYAT, FIYAT, MUHASEBEAD, HARCAMABIRIMAD, AMBARAD, MARKAAD, MODELAD, ISLEMTIPIKOD,YIL,FISNO,DISSICILNO2,GIAI, FISTARIH, BISNO, ESKIBISNO1, EKNO, AMORTIYIL, BULUNDUGUYER, BULUNDUGUYERAD, ISLEMTARIH FROM TASAMBARSICILVIEW LEFT OUTER JOIN TASSICILNORFID ON TASAMBARSICILVIEW.PRSICILNO = TASSICILNORFID.PRSICILNO UNION SELECT SICILNO, HESAPPLANKOD, HESAPPLANAD, KISIAD, ODAAD, ADI, YAZARADI, DISSICILNO, YAYINTARIHI, CILTNO, YERIKONUSU, TASAMBARZIMMETVIEW.PRSICILNO, SASENO, MUHASEBEKOD, HARCAMABIRIMKOD,  AMBARKOD, KIMEGITTI, NEREYEGITTI, TASSICILNORFID.RFIDNO, KDVORAN, KDVLIBIRIMFIYAT, FIYAT, MUHASEBEAD, HARCAMABIRIMAD, AMBARAD, MARKAAD, MODELAD, ISLEMTIPIKOD,YIL,FISNO,DISSICILNO2,GIAI, FISTARIH, BISNO, ESKIBISNO1, EKNO, AMORTIYIL, BULUNDUGUYER, ODAAD, ISLEMTARIH FROM TASAMBARZIMMETVIEW LEFT OUTER JOIN TASSICILNORFID ON TASAMBARZIMMETVIEW.PRSICILNO = TASSICILNORFID.PRSICILNO",""),
            new SQLKomut(32,"TCMB",@"
                                    CREATE PROCEDURE [dbo].[SPHESAPPLANDEGISTIR]
                                    @PRSICILNO INT,
                                    @HESAPPLANKODYENI VARCHAR(50),
                                    @ISLEMYAPAN VARCHAR(25)
                                    AS
                                    BEGIN
                                    BEGIN TRANSACTION;  
  
                                    BEGIN TRY  
                                    IF NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[TASSICILNOHESAPPLANTARIHCE]') AND type in (N'U'))
                                    BEGIN
                                    CREATE TABLE [dbo].[TASSICILNOHESAPPLANTARIHCE](
	                                    [KOD] [int] NOT NULL,
	                                    [ISLEMTARIH] [datetime] NULL,
	                                    [ISLEMYAPAN] [varchar](50) NULL,
	                                    [PRSICILNO] [int] NULL,
	                                    [ESKIDEGER] [varchar](500) NULL,
	                                    [YENIDEGER] [varchar](500) NULL,
	                                    [ACIKLAMA] [varchar](5000) NULL,
                                     CONSTRAINT [PK_TASSICILNOHESAPPLANTARIHCE] PRIMARY KEY CLUSTERED 
                                    (
	                                    [KOD] ASC
                                    )WITH (PAD_INDEX = OFF, STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON) ON [PRIMARY]
                                    ) ON [PRIMARY]
                                    END
                                    declare @aciklama varchar(5000) = '';
                                    declare @hesapPlaniSonSeviyeMi int = 0;
                                    declare @amortismanAdet int = 0;
                                    declare @amortismanOmruYeni int = 0;
                                    declare @HESAPPLANKODESKI varchar(50) = (SELECT HESAPPLANKOD FROM TASSICILNOHAREKET WHERE PRSICILNO = @PRSICILNO AND SIRANO=1)
                                    --Hesap planı son seviye mi?
                                    set @hesapPlaniSonSeviyeMi = (SELECT COUNT(*) FROM TASHESAPPLAN WHERE KOD LIKE @HESAPPLANKODYENI + '%' )
                                    if (@hesapPlaniSonSeviyeMi > 1)
                                    Throw 60000,'Hesap planı son seviye kırılımında olmalıdır.',5
                                    --Amortisman Yapilmis mi?
                                    set @amortismanAdet = (SELECT COUNT(*) FROM TASAMORTISMAN WHERE PRSICILNO = @PRSICILNO)
                                    if (@amortismanAdet = 0)
                                    begin
                                    set @aciklama = 'Amortismanı yapılmamış.'; 
                                    -- Yeni hesap plan kodunun amortiman ömrünü al
                                    set @amortismanOmruYeni = (SELECT AMORTIYIL FROM TASHESAPPLAN WHERE KOD = @HESAPPLANKODYENI)
                                    UPDATE TASSICILNOOZELLIK SET AMORTISMANYIL = @amortismanOmruYeni WHERE PRSICILNO = @PRSICILNO
                                    end
                                    else
                                    begin
	                                    set @aciklama = 'Amortismanı yapılmış.'; 
                                    end
                                    UPDATE TASSICILNOHAREKET SET HESAPPLANKOD = @HESAPPLANKODYENI WHERE PRSICILNO = @PRSICILNO
                                    UPDATE TASISLEMDETAY SET  TASISLEMDETAY.HESAPPLANKOD = @HESAPPLANKODYENI 
                                    FROM TASISLEMDETAY INNER JOIN TASSICILNOHAREKET ON TASSICILNOHAREKET.YIL = TASISLEMDETAY.YIL AND TASSICILNOHAREKET.HARCAMABIRIMKOD = TASISLEMDETAY.HARCAMABIRIMKOD AND TASSICILNOHAREKET.FISNO = TASISLEMDETAY.FISNO AND TASSICILNOHAREKET.FISSIRANO = TASISLEMDETAY.SIRANO 
                                    WHERE TASSICILNOHAREKET.PRSICILNO = @PRSICILNO
                                    AND TASSICILNOHAREKET.ISLEMTURUKOD <> 90 AND TASSICILNOHAREKET.ISLEMTURUKOD <> 46
                                    UPDATE TASZIMMETDETAY SET  TASZIMMETDETAY.HESAPPLANKOD = @HESAPPLANKODYENI 
                                    FROM TASZIMMETDETAY INNER JOIN TASSICILNOHAREKET ON TASSICILNOHAREKET.YIL = TASZIMMETDETAY.YIL AND TASSICILNOHAREKET.HARCAMABIRIMKOD = TASZIMMETDETAY.HARCAMABIRIMKOD AND TASSICILNOHAREKET.FISNO = TASZIMMETDETAY.FISNO AND TASSICILNOHAREKET.PRSICILNO = TASZIMMETDETAY.SICILNO 
                                    WHERE TASSICILNOHAREKET.PRSICILNO = @PRSICILNO 
                                    AND (TASSICILNOHAREKET.ISLEMTURUKOD = 90 OR TASSICILNOHAREKET.ISLEMTURUKOD = 46)
                                    --Tarihçe 
                                    set @aciklama = 'Hesap plan kodu değiştirilidi. ' + @aciklama; 
                                    declare @tasOrtakKod int = (SELECT ISNULL(MAX(KOD),0) + 1 FROM TASSICILNOHESAPPLANTARIHCE);
                                    INSERT INTO [dbo].[TASSICILNOHESAPPLANTARIHCE]
                                               ([KOD]
                                               ,[ISLEMTARIH]
                                               ,[ISLEMYAPAN]
		                                       ,[PRSICILNO]
                                               ,[ESKIDEGER]
                                               ,[YENIDEGER]
		                                       ,[ACIKLAMA])
                                         VALUES
                                               (@tasOrtakKod
                                               ,GETDATE()
                                               ,@ISLEMYAPAN
                                               ,@PRSICILNO
                                               ,@HESAPPLANKODESKI
                                               ,@HESAPPLANKODYENI
		                                       ,@aciklama)
                                    ------------------------------------------------------------------------------------
                                    END TRY  
                                    BEGIN CATCH  
                                        --SELECT ERROR_MESSAGE() AS ErrorMessage  
                                            --ERROR_NUMBER() AS ErrorNumber  
                                            --,ERROR_SEVERITY() AS ErrorSeverity  
                                            --,ERROR_STATE() AS ErrorState  
                                            --,ERROR_PROCEDURE() AS ErrorProcedure  
                                            --,ERROR_LINE() AS ErrorLine  
                                            --,ERROR_MESSAGE() AS ErrorMessage;  
 
                                    DECLARE @Error_Message VARCHAR(5000)
                                    DECLARE @Error_Severity INT
                                    DECLARE @Error_State INT
                                    SELECT @Error_Message = ERROR_MESSAGE()
                                    SELECT @Error_Severity = ERROR_SEVERITY()
                                    SELECT @Error_State = ERROR_STATE()
                                        IF @@TRANCOUNT > 0  
                                            ROLLBACK TRANSACTION;  
		
	                                    RAISERROR (@Error_Message, @Error_Severity, @Error_State)
                                    END CATCH;  
  
                                    IF @@TRANCOUNT > 0  
                                        COMMIT TRANSACTION;  
                                    END","Hesap plan kodu değişikliği için stored procedure ekelendi"),
             new SQLKomut(33,"",@"ALTER TABLE dbo.TASHESAPPLAN ADD VURGULA int NULL","TASHESAPPLAN tablosuna VURGULA alanının eklenmesi."),
             new SQLKomut(34,"",@"ALTER VIEW [dbo].[TASODA]
