                SELECT '00001' AS MUHASEBEKOD, BIRIMKOD AS HARCAMABIRIMKOD, CAST(KOD AS varchar(20)) AS KOD, AD, '' AS AMBARKOD, USTKOD, SEVIYE, KOD AS UKOD, DURUM, MALIYETMERKEZI, 
