             new SQLKomut(2000,"",@"ALTER TABLE dbo.TASAMORTISMANSINIR ADD AMORTISMANSINIRTASIT money NULL","TASAMORTISMANSINIR tablosuna AMORTISMANSINIRTASIT alanının eklenmesi."),
             new SQLKomut(2001,"",@"CREATE TABLE [dbo].[TASTCCBENTEGRASYON](	[KOD] [varchar](50) NOT NULL,	[YIL] [int] NOT NULL,	[MUHASEBEKOD] [varchar](5) NOT NULL,	[HARCAMABIRIMKOD] [varchar](11) NOT NULL,	[FISNO] [varchar](10) NOT NULL,	[REFERANSNO] [varchar](90) NULL,	[SILINDI] [int] NULL, CONSTRAINT [PK_TASTCCBENTEGRASYON] PRIMARY KEY CLUSTERED  (	[KOD] ASC )WITH (PAD_INDEX = OFF, STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON) ON [PRIMARY] ) ON [PRIMARY]",""),
             new SQLKomut(2002,"",@"CREATE NONCLUSTERED INDEX IX_TASHESAPPLAN_ACIKLAMA ON dbo.TASHESAPPLAN (ACIKLAMA) WITH( STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON) ON [PRIMARY]",""),
             new SQLKomut(2003,"",@"CREATE TABLE [dbo].[TASURETIMFORMU](
	                                [KOD] [varchar](40) NOT NULL,
	                                [FISNO] [int] NULL,
