                          dbo.TASAMBAR.HARCAMABIRIMKOD = A.HARCAMABIRIMKOD AND dbo.TASAMBAR.KOD = A.AMBARKOD ON dbo.TASILCE.ILKOD = dbo.TASMUHASEBE.ILKOD AND dbo.TASILCE.KOD = dbo.TASMUHASEBE.ILCEKOD INNER JOIN
