INSERT [dbo].[TASENFLASYONDUZELTMESI] ([KOD], [YIL], [AY], [YIUFE], [SINIR]) VALUES (N'2023-10-3907-4494-aedf-a44737e39336', 2023, 10, CAST(2803.2900000000000 AS Decimal(24, 13)), 0.0000)
INSERT [dbo].[TASENFLASYONDUZELTMESI] ([KOD], [YIL], [AY], [YIUFE], [SINIR]) VALUES (N'2023-11-3907-4494-aedf-a44737e39336', 2023, 11, CAST(2882.0400000000000 AS Decimal(24, 13)), 0.0000)
INSERT [dbo].[TASENFLASYONDUZELTMESI] ([KOD], [YIL], [AY], [YIUFE], [SINIR]) VALUES (N'2023-12-3907-4494-aedf-a44737e39336', 2023, 12, CAST(2915.0200000000000 AS Decimal(24, 13)), 0.0000)","Merkez bankası enflasyon düzelmtesi excel çalışması"),
              new SQLKomut(2020,"",@"ALTER VIEW[dbo].[TASAMBARZIMMETVIEW] AS 
		SELECT A.PRSICILNO, A.SIRANO, A.YIL, A.MUHASEBEKOD, A.HARCAMABIRIMKOD, A.FISNO, A.FISSIRANO, A.SICILNO, A.SICILSIRANO, A.HESAPPLANKOD, A.AMBARKOD, 
        CONVERT(DECIMAL(21, 12), A.FIYAT * ((H1.KDVORAN + 0.0) / 100 + 1) + A.DEGERARTISI) / CONVERT(DECIMAL(21, 12), (H1.KDVORAN + 0.0) / 100 + 1) AS FIYAT, 
        H1.KDVORAN, A.ISLEMTIPIKOD, A.ISLEMTURUKOD, 
        A.ISLEMTARIH, A.ISLEMYAPAN, A.DURUM, A.FISTARIH, A.NEREDENGELDI, A.NEREYEGITTI, A.KIMEGITTI, A.ZIMMETOZELLIK, A.KDVLIBIRIMFIYAT + A.DEGERARTISI AS KDVLIBIRIMFIYAT, A.DEGERARTISI, dbo.TASSICILNOOZELLIK.MARKAKOD, 
        dbo.TASSICILNOOZELLIK.MODELKOD, dbo.TASSICILNOOZELLIK.SASENO, dbo.TASSICILNOOZELLIK.MOTORNO, dbo.TASSICILNOOZELLIK.PLAKA, dbo.TASSICILNOOZELLIK.CILTNO, dbo.TASSICILNOOZELLIK.DIL, 
        dbo.TASSICILNOOZELLIK.YAZARADI, dbo.TASSICILNOOZELLIK.ADI, dbo.TASSICILNOOZELLIK.YAYINYERI, dbo.TASSICILNOOZELLIK.YAYINTARIHI, dbo.TASSICILNOOZELLIK.NEREDENGELDI AS OZELLIKNEREDENGELDI, 
        dbo.TASSICILNOOZELLIK.BOYUTLARI, dbo.TASSICILNOOZELLIK.SATIRSAYISI, dbo.TASSICILNOOZELLIK.YAPRAKSAYISI, dbo.TASSICILNOOZELLIK.SAYFASAYISI, dbo.TASSICILNOOZELLIK.CILTTURU, dbo.TASSICILNOOZELLIK.CESIDI, 
        dbo.TASSICILNOOZELLIK.YERIKONUSU, dbo.TASSICILNOOZELLIK.GELISTARIHI, dbo.TASSICILNOOZELLIK.NEREDEBULUNDU, dbo.TASSICILNOOZELLIK.CAGI, dbo.TASSICILNOOZELLIK.DURUMUMADDESI, 
        dbo.TASSICILNOOZELLIK.ONYUZ, dbo.TASSICILNOOZELLIK.ARKAYUZ, dbo.TASSICILNOOZELLIK.PUAN, dbo.TASSICILNOOZELLIK.FOTOGRAF, dbo.TASSICILNOOZELLIK.DISSICILNO, dbo.TASMUHASEBE.AD AS MUHASEBEAD, 
        dbo.TASHARCAMABIRIM.AD AS HARCAMABIRIMAD, dbo.TASAMBAR.AD AS AMBARAD, dbo.TASHESAPPLAN.ACIKLAMA AS HESAPPLANAD, dbo.TASMARKA.AD AS MARKAAD, dbo.TASMODEL.AD AS MODELAD, 
        dbo.TASPERSONEL.AD AS KISIAD, dbo.TASODA.AD AS ODAAD, dbo.TASPERSONEL.ODA, dbo.TASIL.KOD AS ILKOD, dbo.TASIL.AD AS ILAD, dbo.TASILCE.KOD AS ILCEKOD, dbo.TASILCE.AD AS ILCEAD, 
        dbo.TASOLCUBIRIM.KOD AS OLCUBIRIMKOD, dbo.TASOLCUBIRIM.AD AS OLCUBIRIMAD, dbo.TASSICILNOOZELLIK.DISSICILNO2, dbo.TASSICILNOOZELLIK.GIAI, dbo.TASSICILNOOZELLIK.BISNO, 
        dbo.TASSICILNOOZELLIK.ESKIBISNO1, dbo.TASSICILNOOZELLIK.EKNO, dbo.TASHESAPPLAN.AMORTIYIL, dbo.TASSICILNOOZELLIK.BULUNDUGUYER, dbo.TASODA.AD AS BULUNDUGUYERAD
        FROM dbo.TASMARKA RIGHT OUTER JOIN
        dbo.TASSICILNOOZELLIK LEFT OUTER JOIN
        dbo.TASMODEL ON dbo.TASSICILNOOZELLIK.MARKAKOD = dbo.TASMODEL.MARKAKOD AND dbo.TASSICILNOOZELLIK.MODELKOD = dbo.TASMODEL.KOD RIGHT OUTER JOIN
        dbo.TASILCE INNER JOIN
        dbo.TASAMBAR INNER JOIN
        dbo.TASSICILNOHAREKET AS A INNER JOIN
        dbo.TASHESAPPLAN ON A.HESAPPLANKOD = dbo.TASHESAPPLAN.KOD INNER JOIN
        dbo.TASMUHASEBE ON A.MUHASEBEKOD = dbo.TASMUHASEBE.KOD INNER JOIN
        dbo.TASHARCAMABIRIM ON A.HARCAMABIRIMKOD = dbo.TASHARCAMABIRIM.KOD AND A.MUHASEBEKOD = dbo.TASHARCAMABIRIM.MUHASEBEKOD ON dbo.TASAMBAR.MUHASEBEKOD = A.MUHASEBEKOD AND
        dbo.TASAMBAR.HARCAMABIRIMKOD = A.HARCAMABIRIMKOD AND dbo.TASAMBAR.KOD = A.AMBARKOD ON dbo.TASILCE.ILKOD = dbo.TASMUHASEBE.ILKOD AND dbo.TASILCE.KOD = dbo.TASMUHASEBE.ILCEKOD INNER JOIN
        dbo.TASIL ON dbo.TASILCE.ILKOD = dbo.TASIL.KOD INNER JOIN
        dbo.TASOLCUBIRIM ON dbo.TASHESAPPLAN.OLCUBIRIMKOD = dbo.TASOLCUBIRIM.KOD ON dbo.TASSICILNOOZELLIK.PRSICILNO = A.PRSICILNO ON dbo.TASMARKA.KOD = dbo.TASSICILNOOZELLIK.MARKAKOD LEFT OUTER JOIN
        dbo.TASPERSONEL ON A.KIMEGITTI = dbo.TASPERSONEL.KOD LEFT OUTER JOIN
        dbo.TASODA ON A.NEREYEGITTI = dbo.TASODA.KOD AND A.HARCAMABIRIMKOD = dbo.TASODA.HARCAMABIRIMKOD AND A.MUHASEBEKOD = dbo.TASODA.MUHASEBEKOD
                         
		INNER JOIN TASSICILNOHAREKET AS H1 ON H1.PRSICILNO = A.PRSICILNO AND H1.SIRANO = (SELECT MIN(SIRANO) FROM TASSICILNOHAREKET B   WHERE A.PRSICILNO = B.PRSICILNO AND ISLEMTURUKOD < 50)
						 
		WHERE(A.DURUM <> 2) AND(A.PRSICILNO NOT IN  (SELECT PRSICILNO FROM      dbo.TASSICILNOHAREKET AS B
        WHERE(A.PRSICILNO = PRSICILNO) AND(A.SIRANO < SIRANO) AND(ISLEMTURUKOD = 46 OR
        ISLEMTURUKOD = 47))) AND(A.ISLEMTURUKOD = '90' OR
        A.ISLEMTURUKOD = '91')","Taşınır Sicil Raporu ile Harcama Birimi Taşınır Mal Yönetim Hesabı Cetveli (Örnek 14) tutarsızlığı. KDV değeri sicil hareketin ilk hareketinden alınıyor. Değer artışı her satırda olmadığından en büyük değer artışı dikkate alınıyor."),
              new SQLKomut(2021,"",@"ALTER VIEW[dbo].[TASAMBARSICILVIEW] AS 
        SELECT A.PRSICILNO, A.SIRANO, A.YIL, A.MUHASEBEKOD, A.HARCAMABIRIMKOD, A.FISNO, A.FISSIRANO, A.SICILNO, A.SICILSIRANO, A.HESAPPLANKOD,    
        A.AMBARKOD, (CONVERT(DECIMAL(21, 12),((A.FIYAT*(((H1.KDVORAN+0.0)/100)+1)) + A.DEGERARTISI))/CONVERT(DECIMAL(21, 12), (H1.KDVORAN + 0.0) / 100 + 1))  AS FIYAT, 
        H1.KDVORAN, A.ISLEMTIPIKOD, A.ISLEMTURUKOD, A.ISLEMTARIH, A.ISLEMYAPAN, A.DURUM,   
        A.FISTARIH, A.NEREDENGELDI, A.NEREYEGITTI, A.KIMEGITTI, A.ZIMMETOZELLIK, A.KDVLIBIRIMFIYAT + A.DEGERARTISI AS KDVLIBIRIMFIYAT, A.DEGERARTISI,    
        dbo.TASSICILNOOZELLIK.MARKAKOD, dbo.TASSICILNOOZELLIK.MODELKOD, dbo.TASSICILNOOZELLIK.SASENO, dbo.TASSICILNOOZELLIK.MOTORNO,   
        dbo.TASSICILNOOZELLIK.PLAKA, dbo.TASSICILNOOZELLIK.CILTNO, dbo.TASSICILNOOZELLIK.DIL, dbo.TASSICILNOOZELLIK.YAZARADI,   
        dbo.TASSICILNOOZELLIK.ADI, dbo.TASSICILNOOZELLIK.YAYINYERI, dbo.TASSICILNOOZELLIK.YAYINTARIHI,   
        dbo.TASSICILNOOZELLIK.NEREDENGELDI AS OZELLIKNEREDENGELDI, dbo.TASSICILNOOZELLIK.BOYUTLARI,    
        dbo.TASSICILNOOZELLIK.SATIRSAYISI, dbo.TASSICILNOOZELLIK.YAPRAKSAYISI, dbo.TASSICILNOOZELLIK.SAYFASAYISI,    
        dbo.TASSICILNOOZELLIK.CILTTURU, dbo.TASSICILNOOZELLIK.CESIDI, dbo.TASSICILNOOZELLIK.YERIKONUSU,    
        dbo.TASSICILNOOZELLIK.GELISTARIHI, dbo.TASSICILNOOZELLIK.NEREDEBULUNDU, dbo.TASSICILNOOZELLIK.CAGI,    
        dbo.TASSICILNOOZELLIK.DURUMUMADDESI, dbo.TASSICILNOOZELLIK.ONYUZ, dbo.TASSICILNOOZELLIK.ARKAYUZ, dbo.TASSICILNOOZELLIK.PUAN,   
        dbo.TASSICILNOOZELLIK.FOTOGRAF, dbo.TASSICILNOOZELLIK.DISSICILNO, dbo.TASMUHASEBE.AD AS MUHASEBEAD,   
        dbo.TASHARCAMABIRIM.AD AS HARCAMABIRIMAD, dbo.TASAMBAR.AD AS AMBARAD, dbo.TASHESAPPLAN.ACIKLAMA AS HESAPPLANAD,  
        dbo.TASMARKA.AD AS MARKAAD, dbo.TASMODEL.AD AS MODELAD, dbo.TASSICILNOOZELLIK.DISSICILNO2, dbo.TASSICILNOOZELLIK.GIAI,
        dbo.TASSICILNOOZELLIK.BISNO, dbo.TASSICILNOOZELLIK.ESKIBISNO1, dbo.TASSICILNOOZELLIK.EKNO, dbo.TASHESAPPLAN.AMORTIYIL, 
        dbo.TASSICILNOOZELLIK.BULUNDUGUYER, dbo.TASODA.AD  AS BULUNDUGUYERAD FROM dbo.TASSICILNOHAREKET A 
        INNER JOIN   dbo.TASHESAPPLAN ON A.HESAPPLANKOD = dbo.TASHESAPPLAN.KOD 
        INNER JOIN dbo.TASAMBAR ON A.MUHASEBEKOD = dbo.TASAMBAR.MUHASEBEKOD AND A.HARCAMABIRIMKOD = dbo.TASAMBAR.HARCAMABIRIMKOD AND A.AMBARKOD = dbo.TASAMBAR.KOD 
        INNER JOIN   dbo.TASHARCAMABIRIM ON A.MUHASEBEKOD = dbo.TASHARCAMABIRIM.MUHASEBEKOD AND A.HARCAMABIRIMKOD = dbo.TASHARCAMABIRIM.KOD 
        INNER JOIN   dbo.TASMUHASEBE ON A.MUHASEBEKOD = dbo.TASMUHASEBE.KOD 
        LEFT OUTER JOIN dbo.TASMODEL 
        RIGHT OUTER JOIN dbo.TASSICILNOOZELLIK ON dbo.TASMODEL.MARKAKOD = dbo.TASSICILNOOZELLIK.MARKAKOD AND dbo.TASMODEL.KOD = dbo.TASSICILNOOZELLIK.MODELKOD 
        LEFT OUTER JOIN dbo.TASMARKA ON dbo.TASSICILNOOZELLIK.MARKAKOD = dbo.TASMARKA.KOD ON A.PRSICILNO = dbo.TASSICILNOOZELLIK.PRSICILNO 
        LEFT OUTER JOIN dbo.TASODA ON dbo.TASSICILNOOZELLIK.BULUNDUGUYER = dbo.TASODA.KOD
        INNER JOIN TASSICILNOHAREKET AS H1 ON H1.PRSICILNO = A.PRSICILNO AND H1.SIRANO = (SELECT MIN(SIRANO) FROM TASSICILNOHAREKET B   WHERE A.PRSICILNO = B.PRSICILNO AND ISLEMTURUKOD < 50)
        WHERE (A.ISLEMTURUKOD< 50) AND (A.DURUM<> 2)
        AND(A.PRSICILNO NOT IN   (SELECT PRSICILNO   FROM TASSICILNOHAREKET B   WHERE A.PRSICILNO = B.PRSICILNO AND A.SIRANO<B.SIRANO AND ISLEMTURUKOD >= 50)) 
        AND(A.SIRANO IN   (SELECT MAX(SIRANO) FROM TASSICILNOHAREKET B   WHERE A.PRSICILNO = B.PRSICILNO AND ISLEMTURUKOD < 50))","Taşınır Sicil Raporu ile Harcama Birimi Taşınır Mal Yönetim Hesabı Cetveli (Örnek 14) tutarsızlığı. KDV değeri sicil hareketin ilk hareketinden alınıyor. Değer artışı her satırda olmadığından en büyük değer artışı dikkate alınıyor."),
              new SQLKomut(2022,"TCMB",@"
    INSERT [dbo].[TASENFLASYONDUZELTMESI] ([KOD], [YIL], [AY], [YIUFE], [SINIR]) VALUES (N'2024-01-3907-4494-aedf-a44737e39336', 2024, 1, CAST(3035.5900000000000 AS Decimal(24, 13)), 0.0000)
    INSERT [dbo].[TASENFLASYONDUZELTMESI] ([KOD], [YIL], [AY], [YIUFE], [SINIR]) VALUES (N'2024-02-3907-4494-aedf-a44737e39336', 2024, 2, CAST(3149.0300000000000 AS Decimal(24, 13)), 0.0000)
    INSERT [dbo].[TASENFLASYONDUZELTMESI] ([KOD], [YIL], [AY], [YIUFE], [SINIR]) VALUES (N'2024-03-3907-4494-aedf-a44737e39336', 2024, 3, CAST(3252.7900000000000 AS Decimal(24, 13)), 0.0000)
    INSERT [dbo].[TASENFLASYONDUZELTMESI] ([KOD], [YIL], [AY], [YIUFE], [SINIR]) VALUES (N'2024-04-3907-4494-aedf-a44737e39336', 2024, 4, CAST(3369.9800000000000 AS Decimal(24, 13)), 0.0000)
    INSERT [dbo].[TASENFLASYONDUZELTMESI] ([KOD], [YIL], [AY], [YIUFE], [SINIR]) VALUES (N'2024-05-3907-4494-aedf-a44737e39336', 2024, 5, CAST(3435.9600000000000 AS Decimal(24, 13)), 0.0000)",
                      "Merkez bankası enflasyon düzelmtesi excel çalışması 2"),
              new SQLKomut(2023,"TCMB",@"ALTER VIEW[dbo].[TASAMBARZIMMETVIEW] AS 
		SELECT A.PRSICILNO, A.SIRANO, A.YIL, A.MUHASEBEKOD, A.HARCAMABIRIMKOD, A.FISNO, A.FISSIRANO, A.SICILNO, A.SICILSIRANO, A.HESAPPLANKOD, A.AMBARKOD, 
        CONVERT(DECIMAL(21, 12), A.FIYAT * ((H1.KDVORAN + 0.0) / 100 + 1)) / CONVERT(DECIMAL(21, 12), (H1.KDVORAN + 0.0) / 100 + 1) AS FIYAT, 
        H1.KDVORAN, A.ISLEMTIPIKOD, A.ISLEMTURUKOD, 
        A.ISLEMTARIH, A.ISLEMYAPAN, A.DURUM, A.FISTARIH, A.NEREDENGELDI, A.NEREYEGITTI, A.KIMEGITTI, A.ZIMMETOZELLIK, A.KDVLIBIRIMFIYAT AS KDVLIBIRIMFIYAT, A.DEGERARTISI, dbo.TASSICILNOOZELLIK.MARKAKOD, 
        dbo.TASSICILNOOZELLIK.MODELKOD, dbo.TASSICILNOOZELLIK.SASENO, dbo.TASSICILNOOZELLIK.MOTORNO, dbo.TASSICILNOOZELLIK.PLAKA, dbo.TASSICILNOOZELLIK.CILTNO, dbo.TASSICILNOOZELLIK.DIL, 
        dbo.TASSICILNOOZELLIK.YAZARADI, dbo.TASSICILNOOZELLIK.ADI, dbo.TASSICILNOOZELLIK.YAYINYERI, dbo.TASSICILNOOZELLIK.YAYINTARIHI, dbo.TASSICILNOOZELLIK.NEREDENGELDI AS OZELLIKNEREDENGELDI, 
        dbo.TASSICILNOOZELLIK.BOYUTLARI, dbo.TASSICILNOOZELLIK.SATIRSAYISI, dbo.TASSICILNOOZELLIK.YAPRAKSAYISI, dbo.TASSICILNOOZELLIK.SAYFASAYISI, dbo.TASSICILNOOZELLIK.CILTTURU, dbo.TASSICILNOOZELLIK.CESIDI, 
        dbo.TASSICILNOOZELLIK.YERIKONUSU, dbo.TASSICILNOOZELLIK.GELISTARIHI, dbo.TASSICILNOOZELLIK.NEREDEBULUNDU, dbo.TASSICILNOOZELLIK.CAGI, dbo.TASSICILNOOZELLIK.DURUMUMADDESI, 
        dbo.TASSICILNOOZELLIK.ONYUZ, dbo.TASSICILNOOZELLIK.ARKAYUZ, dbo.TASSICILNOOZELLIK.PUAN, dbo.TASSICILNOOZELLIK.FOTOGRAF, dbo.TASSICILNOOZELLIK.DISSICILNO, dbo.TASMUHASEBE.AD AS MUHASEBEAD, 
        dbo.TASHARCAMABIRIM.AD AS HARCAMABIRIMAD, dbo.TASAMBAR.AD AS AMBARAD, dbo.TASHESAPPLAN.ACIKLAMA AS HESAPPLANAD, dbo.TASMARKA.AD AS MARKAAD, dbo.TASMODEL.AD AS MODELAD, 
        dbo.TASPERSONEL.AD AS KISIAD, dbo.TASODA.AD AS ODAAD, dbo.TASPERSONEL.ODA, dbo.TASIL.KOD AS ILKOD, dbo.TASIL.AD AS ILAD, dbo.TASILCE.KOD AS ILCEKOD, dbo.TASILCE.AD AS ILCEAD, 
        dbo.TASOLCUBIRIM.KOD AS OLCUBIRIMKOD, dbo.TASOLCUBIRIM.AD AS OLCUBIRIMAD, dbo.TASSICILNOOZELLIK.DISSICILNO2, dbo.TASSICILNOOZELLIK.GIAI, dbo.TASSICILNOOZELLIK.BISNO, 
        dbo.TASSICILNOOZELLIK.ESKIBISNO1, dbo.TASSICILNOOZELLIK.EKNO, dbo.TASHESAPPLAN.AMORTIYIL, dbo.TASSICILNOOZELLIK.BULUNDUGUYER, dbo.TASODA.AD AS BULUNDUGUYERAD
        FROM dbo.TASMARKA RIGHT OUTER JOIN
        dbo.TASSICILNOOZELLIK LEFT OUTER JOIN
        dbo.TASMODEL ON dbo.TASSICILNOOZELLIK.MARKAKOD = dbo.TASMODEL.MARKAKOD AND dbo.TASSICILNOOZELLIK.MODELKOD = dbo.TASMODEL.KOD RIGHT OUTER JOIN
        dbo.TASILCE INNER JOIN
        dbo.TASAMBAR INNER JOIN
        dbo.TASSICILNOHAREKET AS A INNER JOIN
        dbo.TASHESAPPLAN ON A.HESAPPLANKOD = dbo.TASHESAPPLAN.KOD INNER JOIN
        dbo.TASMUHASEBE ON A.MUHASEBEKOD = dbo.TASMUHASEBE.KOD INNER JOIN
        dbo.TASHARCAMABIRIM ON A.HARCAMABIRIMKOD = dbo.TASHARCAMABIRIM.KOD AND A.MUHASEBEKOD = dbo.TASHARCAMABIRIM.MUHASEBEKOD ON dbo.TASAMBAR.MUHASEBEKOD = A.MUHASEBEKOD AND
        dbo.TASAMBAR.HARCAMABIRIMKOD = A.HARCAMABIRIMKOD AND dbo.TASAMBAR.KOD = A.AMBARKOD ON dbo.TASILCE.ILKOD = dbo.TASMUHASEBE.ILKOD AND dbo.TASILCE.KOD = dbo.TASMUHASEBE.ILCEKOD INNER JOIN
        dbo.TASIL ON dbo.TASILCE.ILKOD = dbo.TASIL.KOD INNER JOIN
        dbo.TASOLCUBIRIM ON dbo.TASHESAPPLAN.OLCUBIRIMKOD = dbo.TASOLCUBIRIM.KOD ON dbo.TASSICILNOOZELLIK.PRSICILNO = A.PRSICILNO ON dbo.TASMARKA.KOD = dbo.TASSICILNOOZELLIK.MARKAKOD LEFT OUTER JOIN
        dbo.TASPERSONEL ON A.KIMEGITTI = dbo.TASPERSONEL.KOD LEFT OUTER JOIN
        dbo.TASODA ON A.NEREYEGITTI = dbo.TASODA.KOD AND A.HARCAMABIRIMKOD = dbo.TASODA.HARCAMABIRIMKOD AND A.MUHASEBEKOD = dbo.TASODA.MUHASEBEKOD
                         
		INNER JOIN TASSICILNOHAREKET AS H1 ON H1.PRSICILNO = A.PRSICILNO AND H1.SIRANO = (SELECT MIN(SIRANO) FROM TASSICILNOHAREKET B   WHERE A.PRSICILNO = B.PRSICILNO AND ISLEMTURUKOD < 50)
						 
		WHERE(A.DURUM <> 2) AND(A.PRSICILNO NOT IN  (SELECT PRSICILNO FROM      dbo.TASSICILNOHAREKET AS B
        WHERE(A.PRSICILNO = PRSICILNO) AND(A.SIRANO < SIRANO) AND(ISLEMTURUKOD = 46 OR
        ISLEMTURUKOD = 47))) AND(A.ISLEMTURUKOD = '90' OR
        A.ISLEMTURUKOD = '91')","Merkez Bankası için DEGERARTISI FIYAT alanına eklenmedi. Taşınır Sicil Raporu ile Harcama Birimi Taşınır Mal Yönetim Hesabı Cetveli (Örnek 14) tutarsızlığı. KDV değeri sicil hareketin ilk hareketinden alınıyor. Değer artışı her satırda olmadığından en büyük değer artışı dikkate alınıyor."),
              new SQLKomut(2024,"TCMB",@"ALTER VIEW[dbo].[TASAMBARSICILVIEW] AS 
        SELECT A.PRSICILNO, A.SIRANO, A.YIL, A.MUHASEBEKOD, A.HARCAMABIRIMKOD, A.FISNO, A.FISSIRANO, A.SICILNO, A.SICILSIRANO, A.HESAPPLANKOD,    
        A.AMBARKOD, (CONVERT(DECIMAL(21, 12),((A.FIYAT*(((H1.KDVORAN+0.0)/100)+1))))/CONVERT(DECIMAL(21, 12), (H1.KDVORAN + 0.0) / 100 + 1))  AS FIYAT, 
        H1.KDVORAN, A.ISLEMTIPIKOD, A.ISLEMTURUKOD, A.ISLEMTARIH, A.ISLEMYAPAN, A.DURUM,   
        A.FISTARIH, A.NEREDENGELDI, A.NEREYEGITTI, A.KIMEGITTI, A.ZIMMETOZELLIK, A.KDVLIBIRIMFIYAT AS KDVLIBIRIMFIYAT, A.DEGERARTISI,    
        dbo.TASSICILNOOZELLIK.MARKAKOD, dbo.TASSICILNOOZELLIK.MODELKOD, dbo.TASSICILNOOZELLIK.SASENO, dbo.TASSICILNOOZELLIK.MOTORNO,   
        dbo.TASSICILNOOZELLIK.PLAKA, dbo.TASSICILNOOZELLIK.CILTNO, dbo.TASSICILNOOZELLIK.DIL, dbo.TASSICILNOOZELLIK.YAZARADI,   
        dbo.TASSICILNOOZELLIK.ADI, dbo.TASSICILNOOZELLIK.YAYINYERI, dbo.TASSICILNOOZELLIK.YAYINTARIHI,   
        dbo.TASSICILNOOZELLIK.NEREDENGELDI AS OZELLIKNEREDENGELDI, dbo.TASSICILNOOZELLIK.BOYUTLARI,    
        dbo.TASSICILNOOZELLIK.SATIRSAYISI, dbo.TASSICILNOOZELLIK.YAPRAKSAYISI, dbo.TASSICILNOOZELLIK.SAYFASAYISI,    
        dbo.TASSICILNOOZELLIK.CILTTURU, dbo.TASSICILNOOZELLIK.CESIDI, dbo.TASSICILNOOZELLIK.YERIKONUSU,    
        dbo.TASSICILNOOZELLIK.GELISTARIHI, dbo.TASSICILNOOZELLIK.NEREDEBULUNDU, dbo.TASSICILNOOZELLIK.CAGI,    
        dbo.TASSICILNOOZELLIK.DURUMUMADDESI, dbo.TASSICILNOOZELLIK.ONYUZ, dbo.TASSICILNOOZELLIK.ARKAYUZ, dbo.TASSICILNOOZELLIK.PUAN,   
        dbo.TASSICILNOOZELLIK.FOTOGRAF, dbo.TASSICILNOOZELLIK.DISSICILNO, dbo.TASMUHASEBE.AD AS MUHASEBEAD,   
        dbo.TASHARCAMABIRIM.AD AS HARCAMABIRIMAD, dbo.TASAMBAR.AD AS AMBARAD, dbo.TASHESAPPLAN.ACIKLAMA AS HESAPPLANAD,  
        dbo.TASMARKA.AD AS MARKAAD, dbo.TASMODEL.AD AS MODELAD, dbo.TASSICILNOOZELLIK.DISSICILNO2, dbo.TASSICILNOOZELLIK.GIAI,
        dbo.TASSICILNOOZELLIK.BISNO, dbo.TASSICILNOOZELLIK.ESKIBISNO1, dbo.TASSICILNOOZELLIK.EKNO, dbo.TASHESAPPLAN.AMORTIYIL, 
        dbo.TASSICILNOOZELLIK.BULUNDUGUYER, dbo.TASODA.AD  AS BULUNDUGUYERAD FROM dbo.TASSICILNOHAREKET A 
        INNER JOIN   dbo.TASHESAPPLAN ON A.HESAPPLANKOD = dbo.TASHESAPPLAN.KOD 
        INNER JOIN dbo.TASAMBAR ON A.MUHASEBEKOD = dbo.TASAMBAR.MUHASEBEKOD AND A.HARCAMABIRIMKOD = dbo.TASAMBAR.HARCAMABIRIMKOD AND A.AMBARKOD = dbo.TASAMBAR.KOD 
        INNER JOIN   dbo.TASHARCAMABIRIM ON A.MUHASEBEKOD = dbo.TASHARCAMABIRIM.MUHASEBEKOD AND A.HARCAMABIRIMKOD = dbo.TASHARCAMABIRIM.KOD 
        INNER JOIN   dbo.TASMUHASEBE ON A.MUHASEBEKOD = dbo.TASMUHASEBE.KOD 
        LEFT OUTER JOIN dbo.TASMODEL 
        RIGHT OUTER JOIN dbo.TASSICILNOOZELLIK ON dbo.TASMODEL.MARKAKOD = dbo.TASSICILNOOZELLIK.MARKAKOD AND dbo.TASMODEL.KOD = dbo.TASSICILNOOZELLIK.MODELKOD 
        LEFT OUTER JOIN dbo.TASMARKA ON dbo.TASSICILNOOZELLIK.MARKAKOD = dbo.TASMARKA.KOD ON A.PRSICILNO = dbo.TASSICILNOOZELLIK.PRSICILNO 
        LEFT OUTER JOIN dbo.TASODA ON dbo.TASSICILNOOZELLIK.BULUNDUGUYER = dbo.TASODA.KOD
        INNER JOIN TASSICILNOHAREKET AS H1 ON H1.PRSICILNO = A.PRSICILNO AND H1.SIRANO = (SELECT MIN(SIRANO) FROM TASSICILNOHAREKET B   WHERE A.PRSICILNO = B.PRSICILNO AND ISLEMTURUKOD < 50)
        WHERE (A.ISLEMTURUKOD< 50) AND (A.DURUM<> 2)
        AND(A.PRSICILNO NOT IN   (SELECT PRSICILNO   FROM TASSICILNOHAREKET B   WHERE A.PRSICILNO = B.PRSICILNO AND A.SIRANO<B.SIRANO AND ISLEMTURUKOD >= 50)) 
        AND(A.SIRANO IN   (SELECT MAX(SIRANO) FROM TASSICILNOHAREKET B   WHERE A.PRSICILNO = B.PRSICILNO AND ISLEMTURUKOD < 50))","Merkez Bankası için DEGERARTISI FIYAT alanına eklenmedi. Taşınır Sicil Raporu ile Harcama Birimi Taşınır Mal Yönetim Hesabı Cetveli (Örnek 14) tutarsızlığı. KDV değeri sicil hareketin ilk hareketinden alınıyor. Değer artışı her satırda olmadığından en büyük değer artışı dikkate alınıyor."),
              new SQLKomut(2025,"",@"ALTER TABLE dbo.TASIMZA ADD TCKIMLIKNO varchar(11) NULL","TCCB için EBYS entegrasyonunda imzalayacak kişinin TCKimlikNo bilgisi gerekli."),
              new SQLKomut(2026,"",@"CREATE TABLE [dbo].[TASEBYSTCCB](
	                                [EVRAKID] [int] NOT NULL,
	                                [YIL] [int] NULL,
	                                [MUHASEBEKOD] [varchar](50) NULL,
	                                [HARCAMAKOD] [varchar](50) NULL,
	                                [FISNO] [varchar](50) NULL,
	                                [BELGETUR] [int] NULL,
	                                [ISLEMYAPAN] [varchar](100) NULL,
	                                [ISLEMTARIH] [datetime] NULL,
	                                [DURUM] [int] NULL,
                                 CONSTRAINT [PK_TASEBYSCUMHURBASKANLIGI] PRIMARY KEY CLUSTERED 
                                (
	                                [EVRAKID] ASC
                                )
                                ) ON [PRIMARY]","TCCB için EBYS entegrasyon çalışması"),
                new SQLKomut(2027,"",@"CREATE TABLE [dbo].[TASEBYSTCCBBIRIM](
	                                [KOD] [int] NOT NULL,
	                                [AD] [varchar](250) NULL,
	                                [MUHASEBEKOD] [varchar](5) NOT NULL,
	                                [HARCAMAKOD] [varchar](11) NOT NULL,
                                 CONSTRAINT [PK_TASEBYSTCCBBIRIM] PRIMARY KEY CLUSTERED 
                                (
	                                [KOD] ASC
                                )
                                ) ON [PRIMARY]","TCCB için EBYS entegrasyon çalışması, Birim eşleştirme tablosu"),
                new SQLKomut(2030,"",@"ALTER TABLE YERLESKEODA ALTER COLUMN AD varchar(300)
                                       ALTER TABLE YERLESKEODA ALTER COLUMN GORKOD varchar(150)
                                       ALTER TABLE YERLESKEODA ALTER COLUMN GORKODESKI varchar(150)","Merkez Bankasında bu alanlar yeterli olmadığı için değiştirldi."),
                new SQLKomut(2031,"TCMB",@"
                    INSERT [dbo].[TASENFLASYONDUZELTMESI] ([KOD], [YIL], [AY], [YIUFE], [SINIR]) VALUES (N'2024-06-3907-4494-aedf-a44737e39336', 2024, 6, CAST(3483.2500000000000 AS Decimal(24, 13)), 0.0000)
                    INSERT [dbo].[TASENFLASYONDUZELTMESI] ([KOD], [YIL], [AY], [YIUFE], [SINIR]) VALUES (N'2024-07-3907-4494-aedf-a44737e39336', 2024, 7, CAST(3550.8800000000000 AS Decimal(24, 13)), 0.0000)
                    INSERT [dbo].[TASENFLASYONDUZELTMESI] ([KOD], [YIL], [AY], [YIUFE], [SINIR]) VALUES (N'2024-08-3907-4494-aedf-a44737e39336', 2024, 8, CAST(3610.5100000000000 AS Decimal(24, 13)), 0.0000)
                    ",
                      "Merkez bankası enflasyon düzelmtesi excel çalışması 2024.09.30"),
                new SQLKomut(2032,"",@"
                    ALTER TABLE TASSICILNODEGERARTIS ADD KATSAYI decimal(24, 13) NULL
                    ",
                      "TASSICILNODEGERARTIS KATSAYI alanı eklendi"),
                 new SQLKomut(2033,"",@"
                    ALTER TABLE TASSICILNOOZELLIK ADD RFIDETIKETTARIHI datetime NULL
                    ",
                      "TASSICILNOOZELLIK RFIDETIKETTARIHI alanı eklendi"),
                 new SQLKomut(2034,"",@"CREATE TABLE [dbo].[TASRFIDETIKETHAREKET](
	                                    [KOD] [varchar](40) NOT NULL,
	                                    [PRSICILNO] [int] NULL,
	                                    [ISLEMTARIH] [datetime] NULL,
	                                    [ISLEMYAPAN] [varchar](50) NULL,
                                        [ISLEMTUR] [int] NULL,
	                                    [DURUM] [int] NULL,
                                    CONSTRAINT [PK_TASRFIDETIKETHAREKET] PRIMARY KEY CLUSTERED 
                                    (
	                                    [KOD] ASC
                                    )
                                    ) ON [PRIMARY]","RFID Etiket basım işlemlerinin kayıt altına alınması"),
                new SQLKomut(2035,"",@"ALTER VIEW [dbo].[TASODA]
                AS
                SELECT '00001' AS MUHASEBEKOD, BIRIMKOD AS HARCAMABIRIMKOD, CAST(KOD AS varchar(20)) AS KOD, AD, '' AS AMBARKOD, USTKOD, SEVIYE, KOD AS UKOD, DURUM, MALIYETMERKEZI, 
                SIRANO, GORKOD AS KOD2
                FROM dbo.YERLESKEODA","TASODA view için GORKOD alanının eklenmesi."),
                new SQLKomut(2036,"",@"CREATE TABLE [dbo].[TASRFIDYAZICI](
	                                [KOD] [int] NOT NULL,
	                                [IP] [varchar](25) NULL,
	                                [AD] [varchar](100) NULL,
	                                [MUHASEBEKOD] [varchar](5) NOT NULL,
	                                [HARCAMABIRIMKOD] [varchar](11) NOT NULL,
                                 CONSTRAINT [PK_TASRFIDYAZICI] PRIMARY KEY CLUSTERED 
                                (
	                                [KOD] ASC
                                )
                                ) ON [PRIMARY]","RFID Yazıcı tanımlama"),
                 new SQLKomut(2037,"",@"
                    ALTER TABLE TASRFIDETIKETHAREKET ADD ETIKETTURKOD [int] NULL
                    ","TASRFIDETIKETHAREKET ETIKETTURKOD alanı eklendi"),
                 new SQLKomut(2038,"",@"
                    ALTER TABLE TASRFIDETIKETTURU ADD FABAD [varchar](100) NULL
                    ","TASRFIDETIKETTURU FABAD alanı eklendi"),
                 new SQLKomut(2039,"",@"
                    ALTER TABLE TASRFIDYAZICI ALTER COLUMN IP varchar(25)
                    ","TASRFIDYAZICI IP alanı değiştirildi"),
                 new SQLKomut(2039,"",@"
                    ALTER TABLE TASSAYIMAMBAR ALTER COLUMN ODAAD varchar(300)
                    ","TASSAYIMAMBAR ODAAD alanı değiştirildi"),
                  new SQLKomut(2040,"",@"
                    CREATE FUNCTION [dbo].[TASODAALT] (@KOD int)
                        RETURNS TABLE 
                        AS
                        RETURN 
                        (
	                        WITH ALTKOD AS (
                            SELECT KOD, AD, USTKOD
                            FROM YERLESKEODA
                            WHERE KOD = @KOD
                            UNION ALL
                            SELECT h.KOD, h.AD, h.USTKOD
                            FROM YERLESKEODA h
                            JOIN ALTKOD ON h.USTKOD = ALTKOD.KOD
                        )
                        SELECT DISTINCT KOD FROM ALTKOD
                        )
                    ","TASODAALT fonksiyonu eklendi."),
                        new SQLKomut(2024,"TCMB",@"ALTER VIEW[dbo].[TASAMBARSICILVIEW] AS 
        SELECT A.PRSICILNO, A.SIRANO, A.YIL, A.MUHASEBEKOD, A.HARCAMABIRIMKOD, A.FISNO, A.FISSIRANO, A.SICILNO, A.SICILSIRANO, A.HESAPPLANKOD,    
        A.AMBARKOD, (CONVERT(DECIMAL(24, 12),((A.FIYAT*(((H1.KDVORAN+0.0)/100)+1))))/CONVERT(DECIMAL(24, 12), (H1.KDVORAN + 0.0) / 100 + 1))  AS FIYAT, 
        H1.KDVORAN, A.ISLEMTIPIKOD, A.ISLEMTURUKOD, A.ISLEMTARIH, A.ISLEMYAPAN, A.DURUM,   
        A.FISTARIH, A.NEREDENGELDI, A.NEREYEGITTI, A.KIMEGITTI, A.ZIMMETOZELLIK, A.KDVLIBIRIMFIYAT AS KDVLIBIRIMFIYAT, A.DEGERARTISI,    
        dbo.TASSICILNOOZELLIK.MARKAKOD, dbo.TASSICILNOOZELLIK.MODELKOD, dbo.TASSICILNOOZELLIK.SASENO, dbo.TASSICILNOOZELLIK.MOTORNO,   
        dbo.TASSICILNOOZELLIK.PLAKA, dbo.TASSICILNOOZELLIK.CILTNO, dbo.TASSICILNOOZELLIK.DIL, dbo.TASSICILNOOZELLIK.YAZARADI,   
        dbo.TASSICILNOOZELLIK.ADI, dbo.TASSICILNOOZELLIK.YAYINYERI, dbo.TASSICILNOOZELLIK.YAYINTARIHI,   
        dbo.TASSICILNOOZELLIK.NEREDENGELDI AS OZELLIKNEREDENGELDI, dbo.TASSICILNOOZELLIK.BOYUTLARI,    
        dbo.TASSICILNOOZELLIK.SATIRSAYISI, dbo.TASSICILNOOZELLIK.YAPRAKSAYISI, dbo.TASSICILNOOZELLIK.SAYFASAYISI,    
        dbo.TASSICILNOOZELLIK.CILTTURU, dbo.TASSICILNOOZELLIK.CESIDI, dbo.TASSICILNOOZELLIK.YERIKONUSU,    
        dbo.TASSICILNOOZELLIK.GELISTARIHI, dbo.TASSICILNOOZELLIK.NEREDEBULUNDU, dbo.TASSICILNOOZELLIK.CAGI,    
        dbo.TASSICILNOOZELLIK.DURUMUMADDESI, dbo.TASSICILNOOZELLIK.ONYUZ, dbo.TASSICILNOOZELLIK.ARKAYUZ, dbo.TASSICILNOOZELLIK.PUAN,   
        dbo.TASSICILNOOZELLIK.FOTOGRAF, dbo.TASSICILNOOZELLIK.DISSICILNO, dbo.TASMUHASEBE.AD AS MUHASEBEAD,   
        dbo.TASHARCAMABIRIM.AD AS HARCAMABIRIMAD, dbo.TASAMBAR.AD AS AMBARAD, dbo.TASHESAPPLAN.ACIKLAMA AS HESAPPLANAD,  
        dbo.TASMARKA.AD AS MARKAAD, dbo.TASMODEL.AD AS MODELAD, dbo.TASSICILNOOZELLIK.DISSICILNO2, dbo.TASSICILNOOZELLIK.GIAI,
        dbo.TASSICILNOOZELLIK.BISNO, dbo.TASSICILNOOZELLIK.ESKIBISNO1, dbo.TASSICILNOOZELLIK.EKNO, dbo.TASHESAPPLAN.AMORTIYIL, 
        dbo.TASSICILNOOZELLIK.BULUNDUGUYER, dbo.TASODA.AD  AS BULUNDUGUYERAD FROM dbo.TASSICILNOHAREKET A 
        INNER JOIN   dbo.TASHESAPPLAN ON A.HESAPPLANKOD = dbo.TASHESAPPLAN.KOD 
        INNER JOIN dbo.TASAMBAR ON A.MUHASEBEKOD = dbo.TASAMBAR.MUHASEBEKOD AND A.HARCAMABIRIMKOD = dbo.TASAMBAR.HARCAMABIRIMKOD AND A.AMBARKOD = dbo.TASAMBAR.KOD 
        INNER JOIN   dbo.TASHARCAMABIRIM ON A.MUHASEBEKOD = dbo.TASHARCAMABIRIM.MUHASEBEKOD AND A.HARCAMABIRIMKOD = dbo.TASHARCAMABIRIM.KOD 
        INNER JOIN   dbo.TASMUHASEBE ON A.MUHASEBEKOD = dbo.TASMUHASEBE.KOD 
        LEFT OUTER JOIN dbo.TASMODEL 
        RIGHT OUTER JOIN dbo.TASSICILNOOZELLIK ON dbo.TASMODEL.MARKAKOD = dbo.TASSICILNOOZELLIK.MARKAKOD AND dbo.TASMODEL.KOD = dbo.TASSICILNOOZELLIK.MODELKOD 
        LEFT OUTER JOIN dbo.TASMARKA ON dbo.TASSICILNOOZELLIK.MARKAKOD = dbo.TASMARKA.KOD ON A.PRSICILNO = dbo.TASSICILNOOZELLIK.PRSICILNO 
        LEFT OUTER JOIN dbo.TASODA ON dbo.TASSICILNOOZELLIK.BULUNDUGUYER = dbo.TASODA.KOD
        INNER JOIN TASSICILNOHAREKET AS H1 ON H1.PRSICILNO = A.PRSICILNO AND H1.SIRANO = (SELECT MIN(SIRANO) FROM TASSICILNOHAREKET B   WHERE A.PRSICILNO = B.PRSICILNO AND ISLEMTURUKOD < 50)
        WHERE (A.ISLEMTURUKOD< 50) AND (A.DURUM<> 2)
        AND(A.PRSICILNO NOT IN   (SELECT PRSICILNO   FROM TASSICILNOHAREKET B   WHERE A.PRSICILNO = B.PRSICILNO AND A.SIRANO<B.SIRANO AND ISLEMTURUKOD >= 50)) 
        AND(A.SIRANO IN   (SELECT MAX(SIRANO) FROM TASSICILNOHAREKET B   WHERE A.PRSICILNO = B.PRSICILNO AND ISLEMTURUKOD < 50))","Merkez Bankası için DECIMAL(24, 12) olarak değiştirildi."),

        };
    }
}
